contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        // Setup: the test contract is the timelock admin and can grant PROPOSER_ROLE to itself.
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        require(delay >= c.getMinDelay(), "delay must meet minimum delay");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        uint256 timestampBefore = c.getTimestamp(id);
        bool pendingBefore = c.isOperationPending(id);
        bool doneBefore = c.isOperationDone(id);

        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 timestampAfter = c.getTimestamp(id);
        bool pendingAfter = c.isOperationPending(id);
        bool doneAfter = c.isOperationDone(id);

        assert(
            timestampBefore == 0 &&
            !pendingBefore &&
            !doneBefore &&
            !doneAfter &&
            timestampAfter > uint256(1) &&
            timestampAfter == block.timestamp + delay &&
            pendingAfter
        );
    }
}

