contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public payable {
        require(address(this).balance >= value, "insufficient balance");

        bytes32 expectedId = keccak256(abi.encode(target, value, data, predecessor, salt));
        bytes32 actualId = c.hashOperation(target, value, data, predecessor, salt);
        require(actualId == expectedId, "hash mismatch");

        c.grantRole(c.PROPOSER_ROLE(), address(this));
        require(c.hasRole(c.PROPOSER_ROLE(), address(this)), "proposer role not granted");

        uint256 minDelayBefore = c.getMinDelay();
        uint256 safeDelay = minDelayBefore;

        bool scheduleOk;
        try c.schedule(target, value, data, predecessor, salt, safeDelay) {
            scheduleOk = true;
        } catch {
            scheduleOk = false;
        }

        if (!scheduleOk) {
            assert(!c.isOperation(actualId));
        } else {
            require(c.isOperation(actualId), "scheduled operation should be recognized");
            require(c.isOperationPending(actualId), "scheduled operation should be pending");

            uint256 timestamp = c.getTimestamp(actualId);
            require(timestamp == block.timestamp + safeDelay, "timestamp mismatch");

            bool executeReverted;
            try c.execute{value: value}(target, value, data, predecessor, salt) {
                executeReverted = false;
            } catch {
                executeReverted = true;
            }

            assert(executeReverted);
        }
    }
}

