contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 minDelay, uint256 delay, bytes32 salt, address target) public payable {
        require(delay >= minDelay, "delay below minDelay");

        // Set up: scheduler is this contract (constructor grants PROPOSER_ROLE to msg.sender).
        // Schedule an operation that will succeed (empty calldata to a fresh address).
        c.schedule(target, 0, bytes(""), bytes32(0), salt, delay);
        bytes32 id = c.hashOperation(target, 0, bytes(""), bytes32(0), salt);

        // Setup is complete; capture state needed for the invariant.
        uint256 storedDelay = c.getMinDelay();
        bool proposerGranted = c.hasRole(c.PROPOSER_ROLE(), address(this));

        // The rule needs the operation to be executable but not done yet; wait until ready.
        uint256 timestamp = c.getTimestamp(id);
        while (block.timestamp < timestamp) {}

        uint256 balanceBefore = address(c).balance;

        // Recovery: if completion later fails because the executor role is missing,
        // restore it so this test transaction can still end with an assertion.
        try c.execute(target, 0, bytes(""), bytes32(0), salt) {
            // completed
        } catch {
            c.grantRole(c.EXECUTOR_ROLE(), address(this));
        }

        bool operationDone = c.isOperationDone(id);
        bool executorGranted = c.hasRole(c.EXECUTOR_ROLE(), address(this));
        uint256 balanceAfter = address(c).balance;
        bool delayUnchanged = (c.getMinDelay() == storedDelay);

        assert(
            proposerGranted &&
            storedDelay >= minDelay &&
            delayUnchanged &&
            (operationDone == executorGranted) &&
            (balanceAfter == balanceBefore + msg.value)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 minDelay, uint256 delay, bytes32 salt, address target, uint256 amount) public payable {
        require(delay >= minDelay, "delay below minDelay");
        require(address(this).balance >= amount, "insufficient balance");

        // Setup: schedule an operation. This contract has PROPOSER_ROLE from the constructor.
        c.schedule(target, 0, bytes(""), bytes32(0), salt, delay);
        bytes32 id = c.hashOperation(target, 0, bytes(""), bytes32(0), salt);

        // Wait until the operation is ready.
        uint256 timestamp = c.getTimestamp(id);
        while (block.timestamp < timestamp) {}

        // Wait, the executor role may or may not be granted. We want to test the rule:
        // if the caller lacks EXECUTOR_ROLE, execute must revert and the operation stays pending.
        // First, revoke EXECUTOR_ROLE from this contract if it has it, to ensure the revert condition.
        if (c.hasRole(c.EXECUTOR_ROLE(), address(this))) {
            c.revokeRole(c.EXECUTOR_ROLE(), address(this));
        }

        // Now attempt to execute; it should revert because the caller lacks EXECUTOR_ROLE.
        bool reverted;
        try c.execute{value: amount}(target, 0, bytes(""), bytes32(0), salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If it reverted, the operation must still be pending (not done).
        // Also the balance of c should be unchanged (no value transferred).
        bool isPending = c.isOperationPending(id);
        bool isDone = c.isOperationDone(id);
        uint256 balanceAfter = address(c).balance;

        assert(reverted && isPending && !isDone && balanceAfter == amount);
    }

    receive() external payable {}
}

