contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 minDelay, uint256 scheduleDelay, bytes32 salt) public {
        // Use a delay that is at least the current minimum delay, so scheduling is allowed.
        require(scheduleDelay >= minDelay, "test precondition");

        // At this point, the test contract is the timelock admin created in C's constructor,
        // so it can grant the PROPOSER_ROLE to itself and then act as a proposer.
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        // Schedule for an arbitrary target/data/value; only the resulting id matters for the timestamp rule.
        c.schedule(address(this), 0, "", bytes32(0), salt, scheduleDelay);

        bytes32 id = c.hashOperation(address(this), 0, "", bytes32(0), salt);
        uint256 recorded = c.getTimestamp(id);

        // General rule: the timestamp stored for a freshly scheduled operation is exactly
        // the scheduling time plus the delay passed to schedule; it is not the DONE sentinel.
        assert(recorded == block.timestamp + scheduleDelay && recorded > 1);
    }
}

